CREATE TABLE IF NOT EXISTS reward_settings(store_id TEXT PRIMARY KEY REFERENCES stores(id),points_per_real INTEGER NOT NULL CHECK(points_per_real BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS external_api_keys(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),key_hash TEXT NOT NULL UNIQUE,revoked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_usage(key_id TEXT NOT NULL REFERENCES external_api_keys(id),minute INTEGER NOT NULL,hits INTEGER NOT NULL,PRIMARY KEY(key_id,minute));
CREATE TABLE IF NOT EXISTS giveaway_drafts(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),title TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
